import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBarlowCondensed = makeLoadFont('BarlowCondensed');

// Load Barlow Condensed at module level to guarantee it's loaded before frame 0
const { fontFamily } = loadBarlowCondensed();

// Helper to shade colors dynamically for 3D isometric layers
const shadeColor = (color: string, percent: number) => {
  const f = parseInt(color.slice(1), 16),
    t = percent < 0 ? 0 : 255,
    p = percent < 0 ? percent * -1 : percent,
    R = f >> 16,
    G = (f >> 8) & 0x00ff,
    B = f & 0x0000ff;
  return (
    "#" +
    (
      0x1000000 +
      (Math.round((t - R) * p) + R) * 0x10000 +
      (Math.round((t - G) * p) + G) * 0x100 +
      (Math.round((t - B) * p) + B)
    )
      .toString(16)
      .slice(1)
  );
};

// Helper to calculate spring scale transitions
const getSpringScale = (
  frame: number,
  startFrame: number,
  fps: number,
  config?: { damping?: number; mass?: number; stiffness?: number }
) => {
  return spring({
    frame: Math.max(0, frame - startFrame),
    fps,
    config: {
      damping: 12,
      mass: 0.5,
      stiffness: 100,
      ...config,
    },
  });
};

