// 3D Isometric Money Stack Component
const MoneyStack: React.FC<{
  count: number;
  primaryColor?: string;
  progress: number;
}> = ({ count, primaryColor = "#7bc175", progress }) => {
  const bills = Array.from({ length: count }).map((_, i) => i);
  
  return (
    <div style={{ position: "relative", width: "100%", height: 260, display: "flex", alignItems: "flex-end", justifyContent: "center", transition: "none" }}>
      {bills.map((index) => {
        const baseOffset = -index * 13;
        
        // Stagger each bill's drop transition
        const startFrame = index * 0.08;
        const endFrame = startFrame + 0.4;
        const billProgress = Math.min(1, Math.max(0, (progress - startFrame) / (endFrame - startFrame)));
        
        const translateY = (1 - billProgress) * -200 + baseOffset;
        const opacity = billProgress;
        const scale = billProgress === 0 ? 0 : 1 + (1 - billProgress) * 0.15;

        return (
          <div
            key={index}
            style={{
              position: "absolute",
              bottom: 40,
              width: "100%",
              transform: `translateY(${translateY}px) scale(${scale})`,
              opacity,
              zIndex: index,
              transition: "none",
            }}
          >
            <SingleBill primaryColor={primaryColor} />
          </div>
        );
      })}
    </div>
  );
};

// Left or Right Profit Calculation Column Component
const ComparisonColumn: React.FC<{
  label: string;
  value1: number;
  value2: number;
  resultValue: number;
  startFrame: number;
  primaryColor: string;
  secondaryColor: string;
  dividerColor: string;
}> = ({
  label,
  value1,
  value2,
  resultValue,
  startFrame,
  primaryColor,
  secondaryColor,
  dividerColor,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // 1. Header label pop
  const headerStart = startFrame;
  const headerScale = getSpringScale(frame, headerStart, fps);
  const headerOpacity = interpolate(frame, [headerStart, headerStart + 12], [0, 1], { extrapolateRight: "clamp" });

  // 2. Money stacks cascade progress
  const stackStart = startFrame + 10;
  const stackProgress = interpolate(frame, [stackStart, stackStart + 35], [0, 1], { extrapolateRight: "clamp" });

  // 3. Amount values spring scale and count-up
  const valuesStart = startFrame + 15;
  const val1Scale = getSpringScale(frame, valuesStart, fps);
  const val2Scale = getSpringScale(frame, valuesStart + 6, fps);

  const val1Current = Math.round(interpolate(frame, [valuesStart, valuesStart + 30], [0, value1], { extrapolateRight: "clamp" }));
  const val2Current = Math.round(interpolate(frame, [valuesStart + 6, valuesStart + 36], [0, value2], { extrapolateRight: "clamp" }));

  // 4. Minus sign pop
  const minusStart = startFrame + 25;
  const minusScale = getSpringScale(frame, minusStart, fps);

  // 5. Divider line scale
  const dividerStart = startFrame + 32;
  const dividerScaleX = interpolate(frame, [dividerStart, dividerStart + 18], [0, 1], {
    easing: Easing.bezier(0.16, 1, 0.3, 1),
    extrapolateRight: "clamp",
  });

  // 6. Bottom result pop & count-up
  const profitStart = startFrame + 42;
  const profitScale = getSpringScale(frame, profitStart, fps);
  const profitCurrent = Math.round(interpolate(frame, [profitStart, profitStart + 28], [0, resultValue], { extrapolateRight: "clamp" }));

  return (
    <div style={{ display: "flex", flexDirection: "column", width: "100%", alignItems: "center", transition: "none" }}>
      {/* Column Header */}
      <div
        style={{
          fontSize: "4.8rem",
          fontWeight: "900",
          color: secondaryColor,
          letterSpacing: "0.15em",
          marginBottom: "2.5rem",
          opacity: headerOpacity,
          transform: `scale(${headerScale})`,
          transition: "none",
        }}
      >
        {label}
      </div>

      {/* Formula row containing stacks & minus sign */}
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "space-between",
          width: "100%",
          padding: "0 1.5rem",
          transition: "none",
        }}
      >
        {/* Value 1 Stack */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", width: "42%", transition: "none" }}>
          <div
            style={{
              fontSize: "4.5rem",
              fontWeight: "800",
              color: primaryColor,
              marginBottom: "1rem",
              transform: `scale(${val1Scale})`,
              transition: "none",
            }}
          >
            ${val1Current}
          </div>
          <MoneyStack
            count={Math.max(1, Math.round(value1 / 10))}
            primaryColor={primaryColor}
            progress={stackProgress}
          />
        </div>

        {/* Minus Sign */}
        <div
          style={{
            fontSize: "5.5rem",
            fontWeight: "800",
            color: secondaryColor,
            opacity: minusScale,
            transform: `scale(${minusScale})`,
            alignSelf: "center",
            marginBottom: "-40px",
            transition: "none",
          }}
        >
          -
        </div>

        {/* Value 2 Stack */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", width: "42%", transition: "none" }}>
          <div
            style={{
              fontSize: "4.5rem",
              fontWeight: "800",
              color: secondaryColor,
              marginBottom: "1rem",
              transform: `scale(${val2Scale})`,
              transition: "none",
            }}
          >
            ${val2Current}
          </div>
          <MoneyStack
            count={Math.max(1, Math.round(value2 / 10))}
            primaryColor={shadeColor(primaryColor, -0.15)}
            progress={stackProgress}
          />
        </div>
      </div>

      {/* Separator Line */}
      <div
        style={{
          width: "90%",
          height: "4px",
          backgroundColor: dividerColor,
          borderRadius: "2px",
          margin: "2rem 0",
          transform: `scaleX(${dividerScaleX})`,
          transformOrigin: "center",
          transition: "none",
        }}
      />

      {/* Calculation output profit */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scale(${profitScale})`,
          opacity: profitScale,
          transition: "none",
        }}
      >
        <div
          style={{
            fontSize: "6rem",
            fontWeight: "900",
            color: primaryColor,
            lineHeight: "1",
            transition: "none",
          }}
        >
          = ${profitCurrent}
        </div>
        <div
          style={{
            fontSize: "2rem",
            fontWeight: "800",
            color: primaryColor,
            letterSpacing: "0.25em",
            marginTop: "0.6rem",
            transition: "none",
          }}
        >
          PROFIT
        </div>
      </div>
    </div>
  );
};

// Middle Transition Arrow Component
const TransitionArrow: React.FC<{
  startFrame: number;
  secondaryColor?: string;
}> = ({ startFrame, secondaryColor = "#ffffff" }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const arrowScale = getSpringScale(frame, startFrame, fps, { damping: 10 });
  const arrowFloat = Math.sin(frame * 0.12) * 5;

  return (
    <div
      style={{
        width: "100%",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        transform: `scale(${arrowScale}) translateX(${arrowFloat}px)`,
        opacity: arrowScale,
        marginTop: "160px",
        transition: "none",
      }}
    >
      <svg
        viewBox="0 0 100 100"
        style={{
          width: "70px",
          height: "70px",
          fill: secondaryColor,
          filter: "drop-shadow(0px 4px 12px rgba(255,255,255,0.15))",
          transition: "none",
        }}
      >
        <path d="M 15 35 L 55 35 L 55 15 L 85 50 L 55 85 L 55 65 L 15 65 Z" />
      </svg>
    </div>
  );
};

